// field and appends the corresponding JSON patch operations to patchSet.
//
// For each field:
//   - if the field is zero in origMS but non-zero in newMS, an "add" operation is generated at
//     /status/migrationState/<jsonFieldName> (e.g. /status/migrationState/targetNode).
//   - if the field is non-zero in both objects but the values differ, "test" then "replace"
//     operations are generated at that path.
//   - fields whose values are identical are skipped.
//
// When newMS is nil, a "test" followed by a "remove" operation is generated at /status/migrationState
// operating on the whole migration state object.
func addMigrationStateFieldPatches(patchSet *patch.PatchSet, origMS *virtv1.VirtualMachineInstanceMigrationState, newMS *virtv1.VirtualMachineInstanceMigrationState) {
	if newMS == nil {
		patchSet.AddOption(
			patch.WithTest("/status/migrationState", origMS),
			patch.WithRemove("/status/migrationState"),
		)
		return
	}
	if origMS == nil {
		origMS = &virtv1.VirtualMachineInstanceMigrationState{}
	}

	origVal := reflect.ValueOf(*origMS)
	newVal := reflect.ValueOf(*newMS)
	stateType := origVal.Type()

	for i := 0; i < stateType.NumField(); i++ {
		jsonTag := stateType.Field(i).Tag.Get("json")
		if jsonTag == "" || jsonTag == "-" {
			continue
		}
		fieldName := strings.Split(jsonTag, ",")[0]
		if fieldName == "" {
			continue
		}
		path := "/status/migrationState/" + fieldName

		origField := origVal.Field(i)
		newField := newVal.Field(i)
		origZero := origField.IsZero()
		newZero := newField.IsZero()

		switch {
		case origZero && !newZero:
			patchSet.AddOption(patch.WithAdd(path, newField.Interface()))
		case !origZero && !newZero:
			if !apiequality.Semantic.DeepEqual(origField.Interface(), newField.Interface()) {
				patchSet.AddOption(
					patch.WithTest(path, origField.Interface()),
					patch.WithReplace(path, newField.Interface()),
				)
			}
		}
	}
}

